insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_103_v1'
from (values
('127.761.d.1.A',3,'A student reads that people hold rights from nature that no ruler can take away, and that rulers govern with the consent of the governed. This explains major political ideas such as:','["natural law and the social contract", "crop rotation", "building codes", "trade routes"]'::jsonb,0,'Natural law and social contract shaped modern governments.','original'),
('127.761.d.1.A',4,'The idea that government gets its power from the consent of the governed is part of the:','["spoils system", "social contract theory", "divine right of kings", "law of supply"]'::jsonb,1,'Consent underlies social contract thinking.','original'),
('127.761.d.1.B',3,'A chart lists a kingdom ruled by one monarch, a city ruled by a few wealthy families and a state ruled by all citizens. This identifies characteristics of classic forms of government such as:','["sonnets, ballads and odes", "recipes, menus and diets", "monarchy, oligarchy and democracy", "maps, charts and graphs"]'::jsonb,2,'Classic forms differ by who rules.','original'),
('127.761.d.1.B',4,'In an absolute monarchy, political power is held by:','["independent courts", "elected councils", "all citizens equally", "a single ruler with unlimited authority"]'::jsonb,3,'Absolute monarchs are not limited by law.','original'),
('127.761.d.1.C',3,'A student researches careers at the United Nations, in a national agency, in a state office and at a city hall. This explores aspects of:','["public service careers at international, national, state and local levels", "sports careers", "farm jobs only", "private sector sales only"]'::jsonb,0,'Public service exists at every level.','original'),
('127.761.d.1.C',4,'Which job is an example of local public service?','["a retail buyer", "a city planner", "a bank customer", "a movie actor"]'::jsonb,1,'City planners work for local governments.','original'),
('127.761.d.2.A',3,'A class compares the Declaration of Independence''s claims about equality, unalienable rights and government by consent with Enlightenment thinking. This analyzes the:','["uses of electricity", "history of cooking", "principles and ideas underlying the Declaration of Independence", "rules of a board game"]'::jsonb,2,'The Declaration reflects Enlightenment ideas.','original'),
('127.761.d.2.A',4,'According to the Declaration of Independence, governments derive their just powers from:','["foreign rulers", "the wealthiest citizens", "the largest army", "the consent of the governed"]'::jsonb,3,'Consent of the governed.','original'),
('127.761.d.2.B',3,'A student argues that a written constitution makes government powers clear, limited and available to all. This explains the importance of:','["a written constitution and how it organizes the federal government", "secret agreements", "oral promises", "unwritten traditions only"]'::jsonb,0,'A written constitution sets rules.','original'),
('127.761.d.2.B',4,'A written constitution is valuable mainly because it:','["eliminates courts", "defines and limits the powers of government", "removes all laws", "gives rulers unlimited power"]'::jsonb,1,'Clear limits protect liberty.','original'),
('127.761.d.2.C',3,'A reader studies essays written to persuade New Yorkers to ratify the Constitution by explaining separation of powers and checks and balances. This explores the:','["Mayflower Compact", "Articles of Confederation", "Federalist Papers", "Declaration of Rights"]'::jsonb,2,'Federalist Papers argued for ratification.','original'),
('127.761.d.2.C',4,'The Federalist Papers were written to:','["create a navy", "declare independence", "end a war", "explain and defend the proposed U.S. Constitution"]'::jsonb,3,'They promoted ratification.','original'),
('127.761.d.2.D',3,'A court notes that the Constitution lists specific powers for Congress and reserves others to the people and states. This evaluates provisions for:','["limiting the role of government", "avoiding all law", "ending elections", "expanding the role of government without limits"]'::jsonb,0,'Limits include enumerated powers and rights.','original'),
('127.761.d.2.D',4,'Which feature of the Constitution limits government power?','["tax rebates", "the Bill of Rights", "a larger army", "a national holiday"]'::jsonb,1,'The Bill of Rights restrains government.','original'),
('127.761.d.2.E',3,'A student studies how Madison and Jefferson disagreed about the power of a national government and compares their views. This analyzes the contributions of:','["modern pop stars", "chefs", "political philosophies of the founding fathers", "sports teams"]'::jsonb,2,'Founders held differing political philosophies.','original'),
('127.761.d.2.E',4,'James Madison is often called the ''Father of the Constitution'' because he:','["signed treaties with Britain", "wrote the Declaration alone", "led the army", "played a key role in drafting it and the Bill of Rights"]'::jsonb,3,'Madison shaped the document.','original'),
('127.761.d.2.F',3,'A chart shows that states cannot print their own money or make treaties, while the national government cannot take powers not given by the Constitution. This evaluates:','["limits on national and state governments", "limits on cooking", "limits on music", "limits on weather"]'::jsonb,0,'Both levels face limits.','original'),
('127.761.d.2.F',4,'Which power is denied to the states?','["running schools", "coining money", "setting speed limits", "issuing marriage licenses"]'::jsonb,1,'Only the national government coins money.','original'),
('127.761.d.2.G',3,'A student draws a diagram showing the separate branches, their duties and the checks between them. This creates a:','["map of a trip", "recipe chart", "descriptive representation of government organization", "family tree"]'::jsonb,2,'Diagrams show branches and checks.','original'),
('127.761.d.2.G',4,'In the diagram of U.S. government, the branch that makes the laws is the:','["military branch", "executive branch", "judicial branch", "legislative branch"]'::jsonb,3,'Congress makes laws.','original'),
('127.761.d.2.H',3,'A timeline of disputes from the Articles of Confederation to modern debates over federal and state authority shows long-running conflict over:','["the respective roles of national and state governments", "school lunches", "sports leagues", "television ratings"]'::jsonb,0,'Federalism disputes recur.','original'),
('127.761.d.2.H',4,'The system dividing power between a central government and state governments is called:','["theocracy", "federalism", "monarchy", "anarchy"]'::jsonb,1,'Federalism shares power.','original'),
('127.761.d.2.I',3,'A research project profiles Madison, Marshall and Hamilton and explains what each did for government. This identifies:','["well-known chefs", "popular singers", "significant individuals and their roles in the field of government", "famous athletes"]'::jsonb,2,'Individuals shaped government.','original'),
('127.761.d.2.I',4,'John Marshall is best known as the Chief Justice who:','["drafted the Bill of Rights", "led the Continental Army", "wrote the Declaration", "established judicial review in Marbury v. Madison"]'::jsonb,3,'Marbury established judicial review.','original'),
('127.761.d.3.A',3,'A student compares how power is shared in the United States, in a country ruled by one party and in a constitutional monarchy. This compares:','["the U.S. system with other political systems", "two music systems", "two weather systems", "two sports systems"]'::jsonb,0,'Comparing systems reveals differences.','original'),
('127.761.d.3.A',4,'A key difference between a democracy and an authoritarian system is that in a democracy:','["elections are banned", "citizens choose leaders in competitive elections", "the military picks leaders", "one ruler is never challenged"]'::jsonb,1,'Democracy features elections.','original'),
('127.761.d.3.B',3,'An analyst says a presidential system separates the executive from the legislature, while a parliamentary system picks the leader from the legislature. This analyzes:','["advantages of games", "advantages of travel", "advantages and disadvantages of presidential and parliamentary systems", "advantages of diets"]'::jsonb,2,'The systems differ in separation of powers.','original'),
('127.761.d.3.B',4,'In a parliamentary system, the head of government is usually chosen by:','["a national lottery", "the courts", "a single voter", "the legislature"]'::jsonb,3,'Prime minister comes from parliament.','original'),
('127.761.d.4.A',3,'A reader lists freedom of speech, religion, press, assembly and petition from the First Amendment, among others. This identifies the rights guaranteed by the:','["Bill of Rights", "Articles of Confederation", "Magna Carta", "Treaty of Versailles"]'::jsonb,0,'The first ten amendments.','original'),
('127.761.d.4.A',4,'The First Amendment protects the freedom of:','["traveling, shopping and dining", "speech, religion, press, assembly and petition", "buying, selling and trading", "driving, cooking and fishing"]'::jsonb,1,'First Amendment freedoms.','original'),
('127.761.d.4.B',3,'A student argues that rulers must obey the same laws as citizens and that power is limited by law. This evaluates the role of:','["unlimited power", "rule by whim", "limited government and the rule of law in protecting individual rights", "secret courts"]'::jsonb,2,'Law binds government.','original'),
('127.761.d.4.B',4,'The rule of law means that:','["leaders are above the law", "only citizens follow laws", "laws change by whim", "everyone, including officials, must follow the law"]'::jsonb,3,'Equality before the law.','original'),
('127.761.d.4.C',3,'A study of Tinker v. Des Moines and Gideon v. Wainwright identifies issues about speech and counsel. This recognizes issues addressed in:','["critical court cases involving individual rights", "weather reports", "sports finals", "recent movie plots"]'::jsonb,0,'Cases test rights.','original'),
('127.761.d.4.C',4,'Brown v. Board of Education (1954) held that:','["schools must be private", "racial segregation in public schools is unconstitutional", "teachers must be elected", "students may skip school"]'::jsonb,1,'Brown overturned ''separate but equal'' in schools.','original'),
('127.761.d.4.D',3,'A chart shows Congress passing laws that protect rights, the president enforcing them and courts deciding disputes. This defines the:','["roles of cooks", "roles of weather", "roles of each branch in protecting rights", "roles of shoppers"]'::jsonb,2,'Each branch protects rights.','original'),
('127.761.d.4.D',4,'The branch that decides whether a law violates the Constitution is the:','["executive branch", "legislative branch", "military", "judicial branch"]'::jsonb,3,'Courts review laws.','original'),
('127.761.d.4.E',3,'A person arrested is given notice of charges, a hearing and a lawyer, and cannot be punished without fair procedure. This explains the importance of:','["due process rights", "traffic rights", "shopping rights", "parking rights"]'::jsonb,0,'Due process protects fairness.','original'),
('127.761.d.4.E',4,'Due process rights protect individuals from:','["traffic only", "unfair government treatment of life, liberty or property", "taxes only", "weather"]'::jsonb,1,'Fair procedures.','original'),
('127.761.d.4.F',3,'After a Supreme Court decision applies free speech and due process protections to the states, citizens gain protection against state governments too. This recognizes the impact of the:','["Truman Doctrine", "Monroe Doctrine", "incorporation doctrine", "Domino theory"]'::jsonb,2,'Incorporation applies the Bill of Rights to the states.','original'),
('127.761.d.4.F',4,'The Fourteenth Amendment''s due process clause is the basis for:','["creating the Supreme Court", "abolishing the Senate", "ending all state laws", "applying most Bill of Rights protections to state governments"]'::jsonb,3,'Selective incorporation.','original'),
('127.761.d.5.A',3,'Paying taxes and obeying laws are civic duties, while keeping a promise to a friend is a personal one. This explains the difference between:','["personal and civic responsibilities of citizens", "public and private lunches", "wet and dry weather", "old and new coins"]'::jsonb,0,'Both matter in society.','original'),
('127.761.d.5.A',4,'A resident gets a summons to sit on a trial panel next month. Which kind of duty is this?','["personal luxury", "civic responsibility", "sports choice", "private hobby"]'::jsonb,1,'Jury service is a civic duty.','original'),
('127.761.d.5.B',3,'Even in an emergency, a government cannot take away some rights without due process, because they are inviolable. This presents when and why rights:','["belong to officials", "vanish whenever convenient", "of individuals remain protected", "depend on wealth"]'::jsonb,2,'Certain rights are fundamental.','original'),
('127.761.d.5.B',4,'A right described as inviolable means it:','["can be sold", "is optional", "expires yearly", "cannot be taken away or breached without justification"]'::jsonb,3,'Inviolable = not to be violated.','original'),
('127.761.d.5.C',3,'A new tax law changes how much families keep and what services towns can offer. This analyzes the consequences on society of:','["political decisions and actions", "random events", "weather changes", "sports scores"]'::jsonb,0,'Policies have social effects.','original'),
('127.761.d.5.C',4,'Voters can respond to unpopular government decisions by:','["ignoring the decisions", "voting for different leaders", "avoiding the polls", "staying silent"]'::jsonb,1,'Elections are accountability.','original'),
('127.761.d.5.D',3,'A city manager oversees budgets, public works and departments to serve both public and personal needs. This investigates the role of:','["a private bank", "a sports team", "municipal management in serving the community", "a film studio"]'::jsonb,2,'City management provides services.','original'),
('127.761.d.5.D',4,'An example of a service typically managed by municipal government is:','["passport issue", "coinage", "national defense", "water and trash collection"]'::jsonb,3,'Cities run local services.','original'),
('127.761.d.6.A',3,'A group tracks voter turnout, attendance at meetings and changes in policy after a campaign. This presents how to measure the effectiveness of:','["participation in the political process", "a fashion show", "a cooking class", "a sports season"]'::jsonb,0,'Participation can be measured.','original'),
('127.761.d.6.A',4,'One way to measure participation in elections is:','["weather data", "voter turnout", "shoe sizes", "pizza sales"]'::jsonb,1,'Turnout shows engagement.','original'),
('127.761.d.6.B',3,'A student documents how the civil rights marches and a recent petition drive each influenced decisions. This reviews and explains examples of:','["how bread rises", "how stars twinkle", "how citizens and groups have influenced government", "how engines work"]'::jsonb,2,'Citizens shape policy.','original'),
('127.761.d.6.B',4,'A peaceful way for citizens to influence lawmakers is to:','["avoid all politics", "ignore the law", "stay uninformed", "contact their elected representatives"]'::jsonb,3,'Petitioning is a right.','original'),
('127.761.d.6.C',3,'A mayor who invites residents to meetings leads differently from one who decides alone, and turnout changes. This evaluates:','["leadership styles and their impact on participation", "sports uniforms", "school colors", "lunch menus"]'::jsonb,0,'Style affects engagement.','original'),
('127.761.d.6.C',4,'A leader who asks for input and shares decisions is using a:','["autocratic style", "participative or democratic style", "silent style", "no style"]'::jsonb,1,'Participative leaders include others.','original'),
('127.761.d.6.D',3,'Family, school, media and peers all affect what a person believes about government. This explains the factors that influence an individual''s:','["lunch choice", "shoe size", "political attitudes", "eye color"]'::jsonb,2,'Socialization shapes views.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_103_v1'
from (values
('127.761.d.6.D',4,'The process by which people acquire political beliefs from family, school and media is called:','["tax filing", "jury selection", "political isolation", "political socialization"]'::jsonb,3,'Socialization transmits values.','original'),
('127.761.d.6.E',3,'A student compares how effective a governor and a president are at building coalitions, communicating and delivering results. This compares:','["leadership characteristics of state and national leaders", "bridge designs", "cloud types", "leaf shapes"]'::jsonb,0,'Leadership traits matter at every level.','original'),
('127.761.d.6.E',4,'A trait that helps an elected leader govern effectively is:','["secrecy only", "the ability to communicate and build coalitions", "ignoring advisers", "avoiding voters"]'::jsonb,1,'Communication and cooperation.','original'),
('127.761.d.6.F',3,'A civic club organizes a neighborhood cleanup that leads the city to add recycling bins. This explains the importance of:','["avoiding service", "hiding problems", "volunteer public service in bringing about change", "paid work only"]'::jsonb,2,'Volunteers drive change.','original'),
('127.761.d.6.F',4,'Volunteer public service can strengthen a community by:','["raising fines", "reducing involvement", "lowering turnout", "addressing needs and building civic bonds"]'::jsonb,3,'Service builds community.','original'),
('127.761.d.6.F',3,'A state limits factory runoff, and a nearby river becomes cleaner and healthier. This connects a positive effect of a government policy to the:','["physical environment", "school calendar", "sports season", "movie schedule"]'::jsonb,0,'Policy can improve environmental conditions.','original'),
('127.761.d.6.F',4,'A government policy that allows heavy dumping of waste near a river could have a negative effect on the:','["parade routes", "physical environment and water quality", "library hours", "bus colors"]'::jsonb,1,'Policy affects the environment.','original'),
('127.761.d.7.A',3,'A student points to the Civil Rights Act and explains how a political decision shifted social attitudes and law. This identifies a political decision that:','["had no effect", "was never debated", "changed American society", "happened abroad only"]'::jsonb,2,'Policy can shape society.','original'),
('127.761.d.7.A',4,'The Civil Rights Act of 1964 prohibited discrimination based on:','["favorite foods", "hobbies", "height", "race, color, religion, sex or national origin"]'::jsonb,3,'Landmark civil rights law.','original'),
('127.761.d.7.B',3,'Programs like the GI Bill and public school integration altered family life, work and neighborhoods. This discusses changes in culture brought about by:','["government policies", "fashion trends", "weather patterns", "sports leagues"]'::jsonb,0,'Policy shapes culture.','original'),
('127.761.d.7.B',4,'The GI Bill helped many veterans by funding:','["vacations", "education and home loans", "luxury cars", "pets"]'::jsonb,1,'Postwar benefits.','original'),
('127.761.d.7.C',3,'A report shows how farm subsidies affect grain growers differently from tech workers. This presents an example of a policy that affected:','["only the weather", "no one", "a particular group of people", "only machines"]'::jsonb,2,'Policies affect groups unequally.','original'),
('127.761.d.7.C',4,'A government subsidy is a payment intended to:','["end all trade", "reduce all taxes", "punish a business", "support a particular industry or activity"]'::jsonb,3,'Subsidies aid sectors.','original'),
('127.761.d.7.D',3,'Labor unions, the NAACP and business lobbies each pressed lawmakers on bills. This explains the influence of:','["individuals and groups that have affected government policy", "pets", "weather", "tourists"]'::jsonb,0,'Interest groups influence policy.','original'),
('127.761.d.7.D',4,'An interest group is an organization that:','["runs the Supreme Court", "tries to influence government decisions", "prints money", "drafts maps"]'::jsonb,1,'Lobbying shapes policy.','original'),
('127.761.d.8.A',3,'A student draws conclusions about why a port like Houston matters to national trade and politics. This draws conclusions about:','["the price of shoes", "the taste of food", "the political significance of geography to the United States", "the length of songs"]'::jsonb,2,'Geography affects politics and economy.','original'),
('127.761.d.8.A',4,'A country''s location along coastlines and rivers can affect its:','["birthday traditions", "music tastes", "fashion only", "trade, defense and political influence"]'::jsonb,3,'Geography shapes strategy.','original'),
('127.761.d.8.B',3,'A district map shows how mountains and rivers shaped boundaries and the rules for crossing them. This interprets geographical influences on:','["requirements for international, national and state boundaries", "hairstyles", "recipes", "board games"]'::jsonb,0,'Natural features shape borders.','original'),
('127.761.d.8.B',4,'A river is often used as a boundary because it is:','["man-made", "a natural, easily identified feature", "invisible", "moveable at will"]'::jsonb,1,'Rivers mark borders.','original'),
('127.761.d.8.C',3,'A planner predicts how a growing population and limited water will change a region over decades. This predicts how:','["a shirt changes color", "a recipe changes flavor", "geographical considerations affect regional change over time", "a song changes pitch"]'::jsonb,2,'Geography influences change.','original'),
('127.761.d.8.C',4,'Population growth in a dry region may lead to:','["less need for planning", "fewer concerns about water", "no change", "greater demand for water policy and infrastructure"]'::jsonb,3,'Resource limits matter.','original'),
('127.761.d.8.D',3,'A city places a monument and a flag at its government plaza to represent shared history and values. This interprets the importance of:','["cultural symbols in government planning", "private signs", "random decorations", "business logos"]'::jsonb,0,'Symbols express identity.','original'),
('127.761.d.8.D',4,'National symbols such as flags and monuments help to:','["avoid civic life", "express shared identity and values", "hide history", "increase taxes"]'::jsonb,1,'Symbols unite citizens.','original'),
('127.761.d.8.E',3,'Using GIS, an agency layers maps of roads, floods and population to decide where to place shelters. This explores how GIS assists in:','["painting", "singing", "gathering information for government decisions", "cooking"]'::jsonb,2,'GIS organizes spatial data.','original'),
('127.761.d.8.E',4,'A geographic information system (GIS) is a tool for:','["baking bread", "tuning engines", "grading papers", "mapping and analyzing spatial data"]'::jsonb,3,'GIS maps data.','original'),
('127.761.d.9.A',3,'Delegates at the Constitutional Convention argued about representation and reached the Great Compromise. This recalls historical debates and the:','["compromises necessary to reach agreement", "lack of agreement", "failure of talks", "absence of debate"]'::jsonb,0,'Compromise formed the Constitution.','original'),
('127.761.d.9.A',4,'The Great Compromise created a Congress with:','["only one chamber", "a House by population and a Senate with equal votes per state", "rotating leaders", "two Houses by population"]'::jsonb,1,'Balanced large and small states.','original'),
('127.761.d.9.B',3,'Candidates, parties and interest groups use ads, rallies and lobbying to shape what government does. This gives examples of the processes used to:','["delay elections", "ignore policy", "influence public policy", "avoid voters"]'::jsonb,2,'Many actors seek influence.','original'),
('127.761.d.9.B',4,'Lobbying is an effort to:','["count votes", "arrest officials", "draft maps", "persuade lawmakers on policy"]'::jsonb,3,'Lobbyists advocate.','original'),
('127.761.d.9.C',3,'After a movement for women''s suffrage, voting laws changed nationwide. This explores the impact of political changes brought about by:','["individuals and groups", "accidents only", "luck only", "weather only"]'::jsonb,0,'Movements drive change.','original'),
('127.761.d.9.C',4,'The Nineteenth Amendment guaranteed the right to vote regardless of:','["age", "sex", "height", "income"]'::jsonb,1,'Women''s suffrage.','original'),
('127.761.d.9.D',3,'A student shows how beliefs like liberty, equality and self-government appear in the Constitution''s structure. This recognizes how American beliefs and principles are reflected in:','["a phone manual", "a sports rulebook", "the U.S. Constitution", "a recipe book"]'::jsonb,2,'Principles shape the Constitution.','original'),
('127.761.d.9.D',4,'The principle that political power comes from the people is called:','["autocracy", "feudalism", "divine right", "popular sovereignty"]'::jsonb,3,'Popular sovereignty.','original'),
('127.761.d.9.E',3,'A review checks whether agencies, courts and legislatures follow the same goals and avoid overlap. This evaluates the:','["alignment of institutions of government and public administration", "alignment of text boxes", "alignment of music keys", "alignment of car wheels"]'::jsonb,0,'Institutions should work together.','original'),
('127.761.d.9.E',4,'Public administration refers to:','["writing novels", "carrying out government policy and programs", "making films", "coaching teams"]'::jsonb,1,'Administrators implement policy.','original'),
('127.761.d.9.F',3,'A trade agreement or sanctions affect jobs and prices in other countries. This analyzes how:','["fish migrate", "trees grow", "U.S. foreign policy affects other countries", "clouds form"]'::jsonb,2,'Policy has international effects.','original'),
('127.761.d.9.F',4,'Economic sanctions are used by one country to:','["build bridges", "share cultural festivals", "grow crops", "pressure another country to change behavior"]'::jsonb,3,'Sanctions apply pressure.','original'),
('127.761.d.10.A',3,'A student explains that Congress has two houses, writes laws and controls spending. This analyzes the structure and functions of the:','["legislative branch", "executive branch", "judicial branch", "press"]'::jsonb,0,'Congress is bicameral.','original'),
('127.761.d.10.A',4,'Which body can declare war and approve the federal budget?','["the Supreme Court", "Congress", "the Cabinet alone", "the vice president alone"]'::jsonb,1,'Congress holds war and budget powers.','original'),
('127.761.d.10.B',3,'The president enforces laws, commands the military and appoints officials. This analyzes the structure and functions of the:','["legislative branch", "judicial branch", "executive branch", "press"]'::jsonb,2,'The president leads the executive.','original'),
('127.761.d.10.B',4,'The president serves as the nation''s:','["speaker", "clerk", "chief justice", "commander in chief"]'::jsonb,3,'Commander in chief.','original'),
('127.761.d.10.C',3,'Federal courts interpret laws, hear appeals and decide constitutional questions. This analyzes the structure and functions of the:','["judicial branch", "cabinet", "executive branch", "legislative branch"]'::jsonb,0,'Courts interpret law.','original'),
('127.761.d.10.C',4,'Judges on the Supreme Court are appointed by the:','["voters directly", "president, with Senate confirmation", "House alone", "governors"]'::jsonb,1,'Appointed and confirmed.','original'),
('127.761.d.10.D',3,'Agencies like the EPA and the FCC write rules in their areas and enforce them. This analyzes selected independent executive and regulatory:','["schools", "clubs", "agencies and their functions", "sports leagues"]'::jsonb,2,'Agencies regulate.','original'),
('127.761.d.10.D',4,'A regulatory agency such as the Environmental Protection Agency mainly:','["elects presidents", "passes constitutional amendments", "tries criminal cases", "creates and enforces rules in its policy area"]'::jsonb,3,'Agencies regulate.','original'),
('127.761.d.10.E',3,'Provisions like the veto, Senate confirmation and judicial review allow branches to limit each other. This explains how the Constitution provides for:','["checks and balances", "single control", "unlimited rule", "no limits"]'::jsonb,0,'Checks and balances.','original'),
('127.761.d.10.E',4,'A presidential veto is a check on the:','["states", "legislative branch", "judicial branch", "press"]'::jsonb,1,'Veto blocks legislation.','original'),
('127.761.d.10.F',3,'One debate asks whether judges should expand law by creative rulings or stick closely to the text. This analyzes issues raised by:','["trade policy", "voting machines", "judicial activism and judicial restraint", "weather alerts"]'::jsonb,2,'Court philosophies differ.','original'),
('127.761.d.10.F',4,'Judicial restraint means that judges should:','["write new laws", "campaign for office", "ignore precedent", "defer to elected branches and avoid creating new policy"]'::jsonb,3,'Restraint favors deference.','original'),
